"""Merge retained citations with verified primary-source additions; no network in rebuild."""
import json,re,csv
from pathlib import Path
from e9b_core import O,R,save,dump

def main(out=O):
 old=json.loads((out/'baseline/citation_catalog.json').read_text());new=json.loads((out/'literature/new_doi_records.json').read_text());records=list(old)
 years={'R33':2010,'R34':2016,'R35':2008,'R36':2021,'R37':2024,'R39':2018}
 urls={'R33':'https://rss.onlinelibrary.wiley.com/doi/abs/10.1111/j.1467-9868.2009.00726.x','R34':'https://www.sciencedirect.com/science/article/pii/S0169207016000327','R35':'https://journals.ametsoc.org/abstract/journals/mwre/136/11/2008mwr2329.1.xml','R36':'https://arxiv.org/abs/2008.03033','R37':'https://aclanthology.org/2024.findings-naacl.208/','R39':'https://aclanthology.org/P18-1183/'}
 normalize=lambda x:re.sub(r'[^a-z0-9]','',x.lower())
 for r in new:
  assert normalize(r['title'])==normalize(r['expected_title']),r
  r.update(year_cited=years[r['id']],url='https://doi.org/'+r['doi'],primary_verification_url=urls[r['id']],status='DOI_AND_PRIMARY_RECORD_VERIFIED',reading_scope='Primary author/publisher abstract or selected method sections; not exhaustive systematic review')
  records.append(r)
 records.append(dict(id='R38',title='Assessing Look-Ahead Bias in Stock Return Predictions Generated By GPT Sentiment Analysis',year_cited=2023,authors=[dict(given='Paul',family='Glasserman'),dict(given='Caden',family='Lin')],venue='arXiv preprint arXiv:2309.17322',doi='10.48550/arXiv.2309.17322',url='https://arxiv.org/abs/2309.17322',primary_verification_url='https://business.columbia.edu/pglasserman',status='AUTHOR_PREPRINT_VERIFIED',notes='Cite the inspected2023 author preprint. Columbia author list additionally confirms2024 Journal of Financial Data Science6(1),25-42; no unverified journal DOI supplied.',checked_date='2026-11-15'))
 records.append(dict(id='R40',title='Deep Learning for Event-Driven Stock Prediction',year_cited=2015,authors=[dict(given='Xiao',family='Ding'),dict(given='Yue',family='Zhang'),dict(given='Ting',family='Liu'),dict(given='Junwen',family='Duan')],venue='Proceedings of IJCAI2015',pages='2327–2333',doi='',url='https://ijcai.org/proceedings/2015/329',primary_verification_url='https://www.ijcai.org/Proceedings/15/Papers/329.pdf',status='PRIMARY_PROCEEDINGS_VERIFIED_NO_DOI_CLAIM',checked_date='2026-11-15'))
 records.sort(key=lambda r:r['id']);assert len(records)==40;dump(out/'literature/citation_catalog.json',records)
 lines=[];rows=[]
 for r in records:
  authors='; '.join(a.get('literal',a.get('family','')+', '+a.get('given','')) for a in r['authors'])
  if r['id']=='R32':authors='Brock, William; Lakonishok, Josef; LeBaron, Blake'
  venue=r.get('venue','')
  if r.get('volume'):venue+=' '+r['volume']+('('+r['issue']+')' if r.get('issue') else '')
  if r.get('pages'):venue+=', '+r['pages']
  url='https://doi.org/'+r['doi'] if r.get('doi') else r['url']
  lines.append(f"[{r['id']}] {authors} ({r['year_cited']}). {r['title']}. {venue}. {url}")
  rows.append(dict(reference_id=r['id'],year=r['year_cited'],citation_title=r['title'],DOI=r.get('doi',''),primary_url=r.get('primary_verification_url',url),status=r['status'],checked_date=r.get('checked_date','2026-11-14'),reading_scope=r.get('reading_scope','Primary record and abstract; see notes'),notes=r.get('resolution',r.get('notes',''))))
 (out/'literature/REFERENCES.md').write_text('\n\n'.join(lines)+'\n');save(__import__('pandas').DataFrame(rows),out/'literature/citation_audit.csv')
 print('Citations40: retained32 +8 verified additions')
if __name__=='__main__':main()
